    \item[2] reflection through 2 axis
    \item[3] anticorner rotation by $\theta_1$ (or rot$^n$ by $\theta_1$)
\end{enumerate}

\[
\Rightarrow [T_1] = \begin{bmatrix} \cos(-\theta_1) & -\sin(-\theta_1) \\ \sin(-\theta_1) & \cos(-\theta_1) \end{bmatrix} \begin{bmatrix} 1 & 0 \\ 0 & -1 \end{bmatrix} \begin{bmatrix} \cos\theta_1 & -\sin\theta_1 \\ \sin\theta_1 & \cos\theta_1 \end{bmatrix}
\]

\[
= \begin{bmatrix} \cos\theta_1 & \sin\theta_1 \\ -\sin\theta_1 & \cos\theta_1 \end{bmatrix} \begin{bmatrix} \cos\theta_1 & -\sin\theta_1 \\ -\sin\theta_1 & -\cos\theta_1 \end{bmatrix} = \begin{bmatrix} \cos^2\theta_1 - \sin^2\theta_1 & -2\sin\theta_1\cos\theta_1 \\ -2\sin\theta_1\cos\theta_1 & \sin^2\theta_1 - \cos^2\theta_1 \end{bmatrix}
\]

\[
[T_1] = \begin{bmatrix} \cos 2\theta_1 & -\sin 2\theta_1 \\ -\sin 2\theta_1 & -\cos 2\theta_1 \end{bmatrix}
\]

Similarly $[T_2] = \begin{bmatrix} \cos 2\theta_2 & -\sin 2\theta_2 \\ -\sin 2\theta_2 & -\cos 2\theta_2 \end{bmatrix}$

\[
[T_1 \circ T_2] = \begin{bmatrix} \cos 2\theta_1 & -\sin 2\theta_1 \\ -\sin 2\theta_1 & -\cos 2\theta_1 \end{bmatrix} \begin{bmatrix} \cos 2\theta_2 & -\sin 2\theta_2 \\ -\sin 2\theta_2 & -\cos 2\theta_2 \end{bmatrix}
\]

\[
= \begin{bmatrix} \cos(2\theta_1 + 2\theta_2) & \sin(2\theta_1 - 2\theta_2) \\ -\sin(2\theta_1 - 2\theta_2) & \cos(2\theta_1 - 2\theta_2) \end{bmatrix}
\]

(b) \quad $[T_2 \circ T_1] = \begin{bmatrix} \cos(2(\theta_2 - \theta_1)) & \sin(2(\theta_2 - \theta_1)) \\ -\sin(2(\theta_2 - \theta_1)) & \cos(2(\theta_2 - \theta_1)) \end{bmatrix}$

\[
= \begin{bmatrix} \cos(2(\theta_1 - \theta_2)) & -\sin(2(\theta_1 - \theta_2)) \\ \sin(2(\theta_1 - \theta_2)) & \cos(2(\theta_1 - \theta_2)) \end{bmatrix} = \text{Rotation by } 2(\theta_1 - \theta_2)
\]

Hence it is a rotation in $\mathbb{R}^2$

