\]
\[
[T_2] = \begin{bmatrix} \cos(2\theta_2) & \sin(2\theta_2) \\ \sin(2\theta_2) & -\cos(2\theta_2) \end{bmatrix}
\]
\[
[T_2 \circ T_1] = [T_2][T_1]
\]
\[
= \begin{bmatrix} \cos(2\theta_1)(\cos(2\theta_2) + \sin(2\theta_1)\sin(2\theta_2)) & \cos(2\theta_2)\sin(2\theta_1) - \cos(2\theta_1)\sin(2\theta_2) \\ \cos(2\theta_1)\sin(2\theta_2) - \cos(2\theta_2)\sin(2\theta_1) & \sin(2\theta_1)\sin(2\theta_2) + \cos(2\theta_1)\cos(2\theta_2) \end{bmatrix}
\]
By Trigonometric Identities
\[
[T_2 \circ T_1] = \begin{bmatrix} \cos(2(\theta_2 - \theta_1)) & -\sin(2(\theta_2 - \theta_1)) \\ \sin(2(\theta_2 - \theta_1)) & \cos(2(\theta_2 - \theta_1)) \end{bmatrix}
\]

