\noindent Jackpot

\noindent Since let $E = A_1 \vec{x} = \vec{b}_1$ \hfill $E$ can be represented uniquely by $[A_1 | \vec{b}_1]$ \\
\hfill $E' = A_2 \vec{x} = \vec{b}_2$ \hfill $E'$ can also be represented uniquely by $[A_2 | \vec{b}_2]$

\noindent Since $E$ and $E'$ have the same solution space, \\
\hfill Reduced Row Echelon form of $[A_1 | \vec{b}_1] = [A_2 | \vec{b}_2]$

\noindent Since we get RREF of $[A_1 | \vec{b}_1]$ by elementary row operations, \\
\hfill $[RREF A_1 | \vec{b}_1] = E_n E_{n-1} \dots E_1 A_1$

\noindent Also, \\
\hfill $[RREF A_2 | \vec{b}_2] = E_n' E_{n-1}' \dots E_1' A_2'$ \\
\hfill Since $[RREF A_1 | \vec{b}_2] = [RREF A_2 | \vec{b}_2]$ \\
\hfill $\Rightarrow E_{n-1} E_{n-1}' = E_n' E_{n-1}' \dots E_1' [A_2 | \vec{b}_2]$

\noindent Since elementary matrices are equivalent to identity, \\
\hfill They are invertible and there inverse is also elementary, \\
\hfill $\therefore [A_1 | \vec{b}_1] = E_1^{-1} E_2^{-1} \dots E_{n-1}^{-1} E_n^{-1} E_{n-1}^{-1} \dots E_1^{-1} [A_2 | \vec{b}_2]$

\noindent $\therefore [A_1 | \vec{b}_1]$ is equivalent to $[A_2 | \vec{b}_2]$

\noindent Hence $\boxed{E \text{ is equivalent } E'}$

