\noindent Q-1) Space for answering Question-1 only.

\vspace{0.5em}

\noindent (i) for $S$ to be a subspace of $M_{4\times 4}(\mathbb{R})$, it should be closed under addition and multiplication

\vspace{0.5em}

\noindent $S(\vec{y} + \vec{z}) = (\vec{y}_1 + \vec{z}_1) + (\vec{y}_2 + \vec{z}_2) + (\vec{y}_3 + \vec{z}_3) - (\vec{y}_4 + \vec{z}_4)$

\vspace{0.5em}

\noindent $\forall \vec{y}, \vec{z} \in M_{4\times 4}(\mathbb{R})$
\[
= \underbrace{(\vec{y}_1 + \vec{y}_2 + \vec{y}_3 - \vec{y}_4)}_{} + \underbrace{(\vec{z}_1 + \vec{z}_2 + \vec{z}_3 - \vec{z}_4)}_{}
\]

\vspace{0.5em}

\noindent $S(\vec{y} + \vec{z}) = S(\vec{y}) + S(\vec{z})$

\vspace{0.5em}

\noindent Hence, $S \subset M_{4\times 4}(\mathbb{R})$ is closed under addition.

\vspace{0.5em}

\noindent Now $S(t\vec{y}) = t\vec{y}_1 + t\vec{y}_2 + t\vec{y}_3 = t\vec{y}_4$

\vspace{0.5em}

\noindent $\forall \vec{y} \in M_{4\times 4}(\mathbb{R}) = t(\vec{y}_1 + \vec{y}_2 + \vec{y}_3 - \vec{y}_4)$

\vspace{0.5em}

\noindent $S(t\vec{y}) = tS(\vec{y})$

\vspace{0.5em}

\noindent Hence, $S \subset M_{4\times 4}(\mathbb{R})$ is closed under multiplication

\vspace{0.5em}

\noindent Hence, proved $S$ is a subspace of $M_{4\times 4}(\mathbb{R})$.

\vspace{0.5em}

\noindent (ii) Basis $B$ of $S = \underbrace{\begin{bmatrix} \vec{x}_1 \\ \vec{x}_2 \\ \vec{x}_3 \\ \vec{x}_4 \end{bmatrix}}_{\longrightarrow \text{Pro}}$

\vspace{0.5em}

\noindent $\forall \vec{x} \in M_{4\times 4}(\mathbb{R})$

\noindent i.e. $\vec{x}_1 + \vec{x}_2 + \vec{x}_3 = \vec{x}_4$

