\noindent so $\hat{U} \cdot \hat{V}_i = \cos\alpha_i$

\noindent Now since $V_i$ forms a basis for $\mathbb{R}^n$ and $\hat{U} \in \mathbb{R}^n$, $\hat{U}$ can be uniquely represented as linear combination of $\hat{V}_i$

\noindent $\Rightarrow \hat{U} = \sum_{i=1}^{n} c_i \, V_i^n$

\noindent take $\hat{V}_j$ on both sides $\hat{U} \cdot \hat{V}_j = \sum_{i=1}^{n} c_i \, \hat{V}_i \cdot \hat{V}_j$

\noindent $\hat{V}_i \cdot \hat{V}_j = \delta_{ij}$ for orthonormal basis

\noindent so $\hat{U} \cdot \hat{V}_j = \sum_{i=1}^{n} c_i \, \delta_{ij}$ \hfill $\Rightarrow \hat{U} \cdot \hat{V}_j = c_j$ \hfill $= \cos\alpha_j$

\noindent also $\|\hat{U}\|^2 = 1 \Rightarrow \sum_{i=1}^{n} c_i^2$ \hfill so $\sum_{i=1}^{n} c_i^2 = 1$

\noindent Now $c_i^2 = \cos^2\alpha_j \Rightarrow 1 - \sin^2\alpha_j$

\noindent so $1 = \sum_{i=1}^{n} c_i^2 = \sum_{i=1}^{n} (1 - \sin^2\alpha_i) \Rightarrow n - \sum_{i=1}^{n} \sin^2\alpha_i = 1$

\noindent So $1 + \sin^2\alpha_1 + \sin^2\alpha_2 \cdots \sin^2\alpha_n = n$

