\noindent For $\lambda = 3$ \quad $[M - 3I]v = 0 \Rightarrow \begin{bmatrix} 0 & 0 \\ 0 & 1 \end{bmatrix} \begin{bmatrix} a \\ b \end{bmatrix} = 0$

\noindent \hspace{2em} $b = 0$ \quad $\therefore$ Basis $= \begin{bmatrix} 1 \\ 0 \end{bmatrix}$

\noindent \hspace{2em} $a = u$

\vspace{1em}

\noindent \underline{For $\lambda = 4$} \quad $[M - 4I]v = 0 \Rightarrow \begin{bmatrix} -1 & 0 \\ 0 & 0 \end{bmatrix} \begin{bmatrix} a \\ b \end{bmatrix} = 0$ \quad Basis $= \begin{bmatrix} 0 \\ 1 \end{bmatrix}$

\vspace{1em}

\noindent \hspace{2em} Constructing eigen P for $M = PDP^{-1}$

\noindent \hspace{2em} $P = \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix}$

\noindent \hspace{2em} $\therefore \begin{bmatrix} 3 & 0 \\ 0 & 4 \end{bmatrix} = \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix} \begin{bmatrix} 3 & 0 \\ 0 & 4 \end{bmatrix} \begin{bmatrix} 1 & 0 \\ 0 & 1 \end{bmatrix}$.

\vspace{1em}

\noindent For $N$, \quad $\det\begin{bmatrix} 4-\lambda & 1 \\ 0 & 3-\lambda \end{bmatrix} = 0$

\noindent \hspace{2em} $\underline{\lambda = 4, 3}$

\vspace{1em}

\noindent \underline{For $\lambda = 4$} \quad $[N - 4I]v = 0 \quad \begin{bmatrix} 0 & 1 \\ 0 & -1 \end{bmatrix} \begin{bmatrix} a \\ b \end{bmatrix} = 0$

\noindent \hspace{2em} $b = 0 \Rightarrow \begin{bmatrix} 1 \\ 0 \end{bmatrix}$

\noindent \hspace{2em} $a = u$ \quad $a + b = 0$ \quad $\Rightarrow \begin{bmatrix} +1 \\ -1 \end{bmatrix}$

\vspace{1em}

\noindent \hspace{2em} For $\lambda = 3$ \quad $[N - 3I]v = 0 \quad \begin{bmatrix} 1 & 1 \\ 0 & 0 \end{bmatrix} \begin{bmatrix} a \\ b \end{bmatrix} = 0$

\noindent \hspace{2em} Basis $= \begin{bmatrix} 1 \\ 0 \end{bmatrix}$

\vspace{1em}

\noindent \hspace{2em} This can be expressed in $N = P^{-1}DP^{-1}I$.

