\noindent\textbf{Solution}: Let $X$ be a non-empty set.
\[ J_x \text{ be the topological space.} \]

\noindent\textbf{Let $B$ is the basis element.}

\noindent\textbf{Let $B$ is a basis of $J_x$.}

\noindent\textbf{Then $B = \{B_1, B_2, \ldots, B_k\}$ has $k$- elements.}

\noindent\textbf{Then $J_x = \{U_1, U_2, U_3, \ldots, U_p\}$}

\noindent\textbf{Here $U_i$ is the union of the elements of $B_i$'s}

\noindent$\therefore, \; p \leq 2^k$. That is $J_x$ has at most $2^k$ open sets.

\vspace{1em}

\noindent\textbf{(ii)} Let $S = \{S_1, S_2, \ldots, S_n\}$ be a subbasis of $J_x$.

\noindent\textbf{Then Basis $B = \{B_1, B_2, \ldots, B_k\}$ where $B_i$ is equal to the intersection of elements of $S$}

\noindent\textbf{That why: $k \leq 2^n$.}

\noindent\textbf{and $J_x = \{U_1, U_2, U_3, \ldots, U_p\}$}

\noindent\textbf{Here, $U_i$ is equal to the union of the elements of $B_i$'s.}

\noindent$\therefore, \; p \leq 2^k$

\noindent$\Rightarrow \boxed{p \leq 2^{2^n}}$

\vspace{1em}

\noindent\textbf{(i) Imp:} Subbasis $\xrightarrow{\text{Intersection}}$ Basis $\xrightarrow{\text{Union}}$ Topology

\noindent\textbf{(i) A is only set with $n$ elements, then it's power set has $2^n$ elements.}

