\noindent\textbf{Sol.}

\vspace{0.3cm}

\noindent Here,
\begin{align*}
x + y + z + w &= 0 \\
x + y + 2z + 4w &= 0 \\
x + 2y - 4z - 3w &= 0
\end{align*}

\vspace{0.3cm}

\noindent Putting $w = 1$, now
\begin{align*}
x + y + z &= -1 \\
x + y + 2z &= -4 \\
x + 2y - 4z &= 3
\end{align*}

\vspace{0.3cm}

\noindent Now,
\[
\begin{bmatrix} 1 & 1 & 1 \\ 1 & 1 & 2 \\ 1 & 2 & -4 \end{bmatrix} \begin{bmatrix} x \\ y \\ z \end{bmatrix} = \begin{bmatrix} -1 \\ -4 \\ 3 \end{bmatrix}
\]

\vspace{0.3cm}

\[
\Delta = \begin{vmatrix} 1 & 1 & 1 \\ 1 & 1 & 2 \\ 1 & 2 & -4 \end{vmatrix} = 1(-4-4) - 1(-4-2) + 1(2-1)
\]
\[
= -8 - 1(-6) + 1 = -8 + 6 + 1 = -1
\]

\vspace{0.3cm}

\[
\Delta x = \begin{vmatrix} -1 & 1 & 1 \\ -4 & 1 & 2 \\ 3 & 2 & -4 \end{vmatrix} = -1(-4-4) - 1(16-6) + 1(-8-3)
\]
\[
= 8 - 10 - 11 = 8 - 21 = -13
\]

\vspace{0.3cm}

\[
\Delta y = \begin{vmatrix} 1 & -1 & 1 \\ 1 & -4 & 2 \\ 1 & 3 & -4 \end{vmatrix} = 1(16-6) + 1(-4-2) + 1(3+4)
\]
\[
= 10 - 6 + 7 = 11
\]

\vspace{0.3cm}

\[
\Delta z = \begin{vmatrix} 1 & 1 & -1 \\ 1 & 1 & -4 \\ 1 & 2 & 3 \end{vmatrix} = 1(3+8) - 1(3+4) - 1(2+1)
\]
\[
= 11 - 7 - 1 = 11 - 8 = 3
\]

\vspace{0.3cm}

\[
x = \frac{\Delta x}{\Delta} = \frac{-13}{-1} = 13 \qquad y = \frac{\Delta y}{\Delta} = \frac{11}{-1} = -11 \qquad z = \frac{\Delta z}{\Delta} = \frac{3}{-1} = -3
\]

