\vspace{0.3cm}

\noindent $\implies \begin{bmatrix} \cos\theta_1 \cos\theta_2 - \sin\theta_1 \sin\theta_2 & -(\sin\theta_2 \cos\theta_1 + \sin\theta_1 \cos\theta_2) \\ \sin\theta_1 \cos\theta_2 + \cos\theta_1 \sin\theta_2 & \cos\theta_1 \cos\theta_2 - \sin\theta_1 \sin\theta_2 \end{bmatrix}$

\vspace{0.3cm}

\noindent $\implies \begin{bmatrix} \cos(\theta_1 + \theta_2) & -\sin(\theta_1 + \theta_2) \\ \sin(\theta_1 + \theta_2) & \cos(\theta_1 + \theta_2) \end{bmatrix}$

\vspace{0.3cm}

\noindent (b) $T_2 \circ T_1 = \begin{bmatrix} \cos(\theta_1 + \theta_2) & -\sin(\theta_1 + \theta_2) \\ \sin(\theta_1 + \theta_2) & \cos(\theta_1 + \theta_2) \end{bmatrix}$

\vspace{0.3cm}

\noindent as $T_2 \circ T_1$ can be written in form of $\begin{pmatrix} \cos\theta' & -\sin\theta' \\ \sin\theta' & \cos\theta' \end{pmatrix}$

\vspace{0.3cm}

\noindent where $\theta' = \theta_1 + \theta_2$, so we can say that $T_2 \circ T_1$ is a rotation of $\mathbb{R}^2$.

\vspace{0.3cm}

\noindent (c) $T_2 \circ T_1 = \begin{bmatrix} \cos(\theta_1 + \theta_2) & -\sin(\theta_1 + \theta_2) \\ \sin(\theta_1 + \theta_2) & \cos(\theta_1 + \theta_2) \end{bmatrix} \quad \therefore$ angle of rotation $= \theta_1 + \theta_2$.

