\[ y = (y_1, \ldots, y_m) \]
\[ f(x) = (f_1(x), f_2(x), \ldots, f_m(x)) \]
\[ f(y) = (f_1(y), f_2(y), \ldots, f_m(y)) \]

\vspace{0.5em}

\noindent $\Rightarrow \sum_{i=1}^{n} (x_i - y_i)^2 = \sum_{i=1}^{m} (f_i(x) - f_i(y))^2$

\vspace{0.5em}

\noindent In particular take $y = (0, 0, \ldots, 0)$

\vspace{0.5em}

\noindent $\Rightarrow \sum_{i=1}^{n} (x_i)^2 = \sum_{i=1}^{m} f_i(x)^2$

\vspace{0.5em}

\noindent take $n = (1, 0, 0, \ldots, 0) = e_1$

\vspace{0.5em}

\noindent $\Rightarrow f_1(x)^2 + f_2(x)^2 + \ldots + f_m(x)^2 = 1$

\vspace{0.5em}

\noindent $\Rightarrow f_1(x)^2 \leq 1$ and $\exists j \in \{1, \ldots, n\}$ s.t $f_j(x)^2 < 1$

\vspace{0.5em}

\noindent But then for $n = \{1, 1, 1, 1, \ldots, 1\}$

\vspace{0.5em}

\noindent $\sum f_i(x)^2 \leq n$

\vspace{0.5em}

\noindent $\Rightarrow \sum_{i=1}^{n} f_i(e_j)^2 = 1$

\vspace{0.5em}

\noindent Now take $n = (1, 1, 1, \ldots, 1)$ \quad $\Rightarrow \sum_{i=1}^{n} f_i(x) = m = f_1(e_1)^2 + \ldots + f_m(e_m)^2$

\vspace{0.5em}

\noindent $\Rightarrow \sum_{i=1}^{n} f_i^2(e_1 + e_2 \ldots e_m) = \sum_{i=1}^{n} f_i(e_1)^2 + \sum_{i=1}^{n} f_i(e_2)^2 + \ldots + \sum_{i=1}^{n} f_i(e_m)^2$

