\noindent (i) \quad $\hat{u} = (u \cdot \hat{v}_1) \hat{v}_1 + (u \cdot \hat{v}_2) \hat{v}_2 + \cdots + (u \cdot \hat{v}_n) \hat{v}_n$

\vspace{1em}

\noindent $\hat{u} = c_1 \hat{v}_1 + c_2 \hat{v}_2 + \cdots + c_n \hat{v}_n$

\vspace{0.5em}

\noindent $(\hat{v}_1 \cdot \hat{u}) = c_1 \|\hat{v}_1\|^2 \implies c_1 = \hat{v}_1 \cdot \hat{u}$

\vspace{0.5em}

\noindent Similarly \quad $c_i = \hat{v}_i \cdot \hat{u}$

\vspace{0.5em}

\noindent $\therefore \hat{u} = \sum_{i=1}^{n} (\hat{u} \cdot \hat{v}_i) \hat{v}_i$

\vspace{0.5em}

\noindent $= \sum_{i=1}^{n} \left( \|\hat{u}\| \|\hat{v}_i\| \cos\alpha_i \right) \hat{v}_i$

\vspace{0.5em}

\noindent $= \sum_{i=1}^{n} (\cos\alpha_i) \hat{v}_i$

\vspace{0.5em}

\noindent $\|\hat{u}\|^2 = \sum_{i=1}^{n} \cos^2\alpha_i$

\vspace{0.5em}

\noindent $\implies 1 = \sum_{i=1}^{n} \left( 1 - \sin^2\alpha_i \right)$

\vspace{0.5em}

\noindent $\implies 1 = n - \sum_{i=1}^{n} \sin^2\alpha_i$

\vspace{0.5em}

\noindent $\implies 1 + \sum_{i=1}^{n} \sin^2\alpha_i = n$

\vspace{0.5em}

\noindent $\implies 1 + \sin^2\alpha_1 + \sin^2\alpha_2 + \cdots \sin^2\alpha_n = n$

