\vspace{0.3cm}

\noindent and $\hat{\mu} \in \mathbb{R}^n$ is a unit vector

\vspace{0.3cm}

\noindent and $\hat{v}_i$ is the angle between $\hat{\mu}$ \& $\hat{v}_i$

\vspace{0.3cm}

\noindent $\cos \alpha_i = \dfrac{v_i \cdot \mu}{|\mu v_i|} = \dfrac{v_i \cdot \mu}{|v_i|}$ \hfill as $\mu$ is unit vector, $|\mu| = 1$

\vspace{0.3cm}

\noindent $\left(\cos \alpha_i\right)^2 = \left(\dfrac{v_i \cdot \mu}{v_i}\right)^2 = 1 - \sin^2 \alpha_i$ \hfill $\left[\text{when, } v_i \cdot \mu = v_i \right.$ \\
\hspace*{2em} $\cos \alpha_i = 1$ \\
\hspace*{2em} only one case, \\
\hspace*{2em} and for rest all \\
\hspace*{2em} $\cos \alpha_i = 0$ \hfill $\left[\text{and for rest all}\right.$

\vspace{0.3cm}

\noindent $\dfrac{n}{\sum_{i=1}^{n}} \cos^2 \alpha_i = \dfrac{n}{\sum_{i=1}^{n}} \left(1 - \sin^2 \alpha_i\right)$

\vspace{0.3cm}

\noindent $1 = n - \left(\sin^2 \alpha_1 + \sin^2 \alpha_2 + \ldots + \sin^2 \alpha_n\right)$

\vspace{0.3cm}

\noindent $1 + \sin^2 \alpha_1 + \sin^2 \alpha_2 + \ldots + \sin^2 \alpha_n = n$

\vspace{0.3cm}

\noindent $\therefore$ hence proved.

\vspace{0.3cm}

\noindent $1 + \sin^2 \alpha_1 + \sin^2 \alpha_2 + \ldots + \sin^2 \alpha_n = n$

