\vspace{0.3cm}

\noindent $\cos^2 \alpha_i = \frac{C_i^2}{C_1^2 + C_2^2 + \cdots + C_n^2}$

\vspace{0.3cm}

\noindent $\sum_{i=1}^{n} \sin^2 \alpha_i = n - \sum_{i=1}^{n} \cos^2 \alpha_i$

