\noindent $A^{-1} \Rightarrow \dfrac{1}{|A|} \operatorname{adj}(A)$ \hfill $|A| = 1(12) - 2(0) + 3(0) = 12$

\vspace{0.3cm}

\noindent $\operatorname{adj}(A) \Rightarrow \begin{bmatrix} 12 & 0 & 0 \\ 12 & 6 & 0 \\ 2 & 4 & 2 \end{bmatrix}^T = \begin{bmatrix} 12 & 12 & 2 \\ 0 & 6 & 4 \\ 0 & 0 & 2 \end{bmatrix}$

\vspace{0.3cm}

\noindent $A^{-1} = \dfrac{1}{12} \begin{bmatrix} 12 & 12 & 2 \\ 0 & 6 & 4 \\ 0 & 0 & 2 \end{bmatrix} = \begin{bmatrix} 1 & 1 & \dfrac{1}{6} \\ 0 & \dfrac{1}{2} & \dfrac{1}{3} \\ 0 & 0 & \dfrac{1}{6} \end{bmatrix}$

\vspace{0.3cm}

\noindent $A = \begin{bmatrix} 1 & 2 & 3 \\ 0 & 2 & 4 \\ 0 & 0 & 6 \end{bmatrix}$

\vspace{0.3cm}

\noindent $\Rightarrow \begin{bmatrix} 1 & 2 & 3 \\ 0 & 2 & 4 \\ 0 & 0 & 6 \end{bmatrix} \xrightarrow{(i-ii)} \begin{bmatrix} 1 & 0 & -1 \\ 0 & 2 & 4 \\ 0 & 0 & 6 \end{bmatrix} \xrightarrow{(i-iii)} \begin{bmatrix} 1 & 0 & -1 \\ 0 & 2 & -2 \\ 0 & 0 & 6 \end{bmatrix} \xrightarrow{=2} \begin{bmatrix} 1 & 0 & -1 \\ 0 & 1 & -1 \\ 0 & 0 & 1 \end{bmatrix}$

\vspace{0.3cm}

\noindent $\Rightarrow \begin{bmatrix} 1 & 0 & 0 \\ 0 & 1 & -1 \\ 0 & 0 & 1 \end{bmatrix} \xrightarrow{(i+iii)} \begin{bmatrix} 1 & 0 & 0 \\ 0 & 1 & 0 \\ 0 & 0 & 1 \end{bmatrix} \xrightarrow{(i+iii)} \begin{bmatrix} 1 & 0 & 0 \\ 0 & 1 & 0 \\ 0 & 0 & 1 \end{bmatrix}$

\vspace{0.3cm}

\noindent $E_1 = \begin{bmatrix} 1 & -1 & 0 \\ 0 & 1 & 0 \\ 0 & 0 & 1 \end{bmatrix} \quad E_2 = \begin{bmatrix} 1 & 0 & 0 \\ 0 & 1 & -1 \\ 0 & 0 & 1 \end{bmatrix} \quad E_3 = \begin{bmatrix} 1 & 0 & 0 \\ 0 & \frac{1}{2} & 0 \\ 0 & 0 & \frac{1}{6} \end{bmatrix} \quad E_4 = \begin{bmatrix} 1 & 0 & 1 \\ 0 & 1 & 0 \\ 0 & 0 & 1 \end{bmatrix} \quad E_5 = \begin{bmatrix} 1 & 0 & 0 \\ 0 & 1 & 1 \\ 0 & 0 & 0 \end{bmatrix}$

\vspace{0.3cm}

\noindent $\therefore E_1 E_2 E_3 E_4 E_5 A = I$. \\
$\therefore E_1 E_2 E_3 E_4 E_5 A = A^{-1}$. \\
$\therefore$ Hence, proved.

\vspace{0.3cm}

\noindent The product of elementary matrices $\Rightarrow$ equal to inverse of the matrix.

\vspace{0.3cm}

\noindent $\Rightarrow E_1 A = A_1$ \\
$\Rightarrow \left[E_1 A_{n-1} = A_n\right]$ \\
$\Rightarrow E_2 A_1 = A_2$ \\
$\Rightarrow E_2(E_1 A) = A_2$ \\
$\Rightarrow E_3(E_2 E_1 A) = A_3$ \\
$\left(\text{As } A_5 = I\right)$ \\
$\left.\begin{array}{l} E_5 A_4 = A_5 \\ E_5(E_4 E_3 E_2 E_1 A) = A_5 \end{array}\right.$

