\vspace{0.3cm}

\noindent $|A - \lambda I| = \begin{vmatrix} 3-\lambda & 0 & 0 & 0 \\ 0 & 5-\lambda & 1 & 0 \\ 0 & 0 & 5-\lambda & 1 \\ 0 & 0 & 0 & 5-\lambda \end{vmatrix} = 0 \quad \Rightarrow (3-\lambda)(5-\lambda)^3 = 0$

\vspace{0.3cm}

\noindent $\Rightarrow \lambda = 3, 5$

\vspace{0.3cm}

\noindent Eigenvalues of $A$ are $\boxed{3, 5}$

\vspace{0.3cm}

\noindent $\lambda = 3$: \quad $A - \lambda I = \begin{bmatrix} 0 & 0 & 0 & 0 \\ 0 & 2 & 1 & 0 \\ 0 & 0 & 2 & 1 \\ 0 & 0 & 0 & 2 \end{bmatrix}$ \quad let $\bar{x} = \begin{bmatrix} x \\ y \\ z \\ w \end{bmatrix}$ be a eigenvector for $\lambda = 3$

\vspace{0.3cm}

\noindent $[A - \lambda I][\bar{x}] = \bar{0} \quad \Rightarrow \begin{bmatrix} 0 & 0 & 0 & 0 \\ 0 & 2 & 1 & 0 \\ 0 & 0 & 2 & 1 \\ 0 & 0 & 0 & 2 \end{bmatrix} \begin{bmatrix} x \\ y \\ z \\ w \end{bmatrix} = \begin{bmatrix} 0 \\ 2y+z \\ 2z+w \\ 2w \end{bmatrix} = \bar{0}$

\vspace{0.3cm}

\noindent $\Rightarrow 2y+z = 0, \quad 2z+w = 0, \quad 2w = 0$

\vspace{0.3cm}

\noindent $\Rightarrow y = z = w = 0$

\vspace{0.3cm}

\noindent Then, $\bar{x} = \begin{bmatrix} x \\ 0 \\ 0 \\ 0 \end{bmatrix} = x \begin{bmatrix} 1 \\ 0 \\ 0 \\ 0 \end{bmatrix}$

\vspace{0.3cm}

\noindent eigenspace for $\lambda = 3$ is $\boxed{\begin{bmatrix} 1 \\ 0 \\ 0 \\ 0 \end{bmatrix}}$

\vspace{0.3cm}

\noindent So, \quad for $\lambda = 3$, algebraic multiplicity $= 1$ \\
\hspace{1.5cm} geometric multiplicity $= 1$ \\
\hspace{1.5cm} Basis for eigenspace $= \begin{bmatrix} 1 \\ 0 \\ 0 \\ 0 \end{bmatrix}$

\vspace{0.3cm}

\noindent \hspace{1.5cm} for $\lambda = 5$, \quad algebraic multiplicity $= 3$ \\
\hspace{1.5cm} geometric multiplicity $= 1$ \\
\hspace{1.5cm} Basis for eigenspace $= \begin{bmatrix} 1 \\ 0 \\ 0 \\ 0 \end{bmatrix}$

