\noindent\textbf{(5)} \quad $\hat{u} =$ unit vector
\[
\{\hat{v}_1, \hat{v}_2, \ldots, \hat{v}_n\} \rightarrow$ orthonormal Basis
\]

\[
\Rightarrow \cos\alpha_1 = \frac{\hat{u} \cdot v_1}{|u| |v_1|} = \frac{\hat{u} \cdot v_1}{|v_2|} \qquad \sin^2\alpha_1 = 1 - \left(\frac{\hat{u} \cdot v_1}{|u|}\right)^2
\]

\[
\cos\alpha_2 = \frac{\hat{u} \cdot v_2}{|u| |v_2|} = \frac{\hat{u} \cdot v_2}{|v_2|} \qquad \sin^2\alpha_2 = 1 - \left(\frac{\hat{u} \cdot v_2}{|u|}\right)^2
\]

\[
\cos\alpha_n = \frac{\hat{u} \cdot v_n}{|u| |v_n|} = \frac{\hat{u} \cdot v_n}{|v_n|} \qquad \sin^2\alpha_n = 1 - \left(\frac{\hat{u} \cdot v_n}{|u|}\right)^2
\]

\[
\boxed{\sum_{i=1}^{n} \sin^2\alpha_i = n - \left(\underbrace{\phantom{1}1}_{n-1}\right)}
\]

\[
\boxed{\left(\frac{\hat{u} \cdot v_1}{|v_1|}\right)^2 + \left(\frac{\hat{u} \cdot v_2}{|v_2|}\right)^2 + \left(\frac{\hat{u} \cdot v_3}{|v_3|}\right)^2 - \left(\frac{\hat{u} \cdot v_n}{|v_n|}\right)^2 = 1}
\]

\noindent\textbf{(so)} \quad $1 + \sin^2\alpha_1 + \cdots + \sin^2\alpha_n = n$ \quad \text{is unit vector} \\
\quad \text{and } (\hat{v}_1, \hat{v}_2, \ldots, \hat{v}_n) \text{ are orthonormal Basis}

