\vspace{0.5em}

\noindent $|M - \lambda I| = 0$

\vspace{0.5em}

\noindent $\begin{vmatrix} 3-\lambda & 0 \\ 0 & 4-\lambda \end{vmatrix} = 0$

\vspace{0.5em}

\noindent $(3-\lambda)(4-\lambda) = 0$

\vspace{0.5em}

\noindent $\lambda = 3, 4$

\vspace{0.5em}

\noindent For $\lambda = 3$, $(M - \lambda I)N = 0$

\vspace{0.5em}

\noindent $\begin{bmatrix} 0 & 0 \\ 0 & 1 \end{bmatrix} \begin{bmatrix} N_1 \\ N_2 \end{bmatrix} = 0$

\vspace{0.5em}

\noindent $N_2 = 0$

\vspace{0.5em}

\noindent Eigenvector for $\lambda = 3 \Rightarrow \left\{ \begin{bmatrix} 1 \\ 0 \end{bmatrix} \right\}$

\vspace{0.5em}

\noindent For $\lambda = 4$, $(M - \lambda I)N = 0$

\vspace{0.5em}

\noindent $\begin{bmatrix} -1 & 0 \\ 0 & 0 \end{bmatrix} \begin{bmatrix} N_1 \\ N_2 \end{bmatrix} = 0$

\vspace{0.5em}

\noindent $-N_1 = 0$

\vspace{0.5em}

\noindent Eigenvector for $\lambda = 4 \Rightarrow \begin{bmatrix} 0 \\ 1 \end{bmatrix}$

\vspace{0.5em}

\noindent Basis for eigenspace $= \left\{ \begin{bmatrix} 1 \\ 0 \end{bmatrix}, \begin{bmatrix} 0 \\ 1 \end{bmatrix} \right\}$

\vspace{0.5em}

\noindent \hspace{2em} $|N - \lambda I| = 0$

\vspace{0.5em}

\noindent $\begin{bmatrix} 4-\lambda & 1 \\ 0 & 3-\lambda \end{bmatrix} = 0$

\vspace{0.5em}

\noindent $(4-\lambda)(3-\lambda) = 0$

\vspace{0.5em}

\noindent $\lambda = 3, 4$

\vspace{0.5em}

\noindent For $\lambda = 3$, $(M - \lambda I)N = 0$

\vspace{0.5em}

\noindent $\begin{bmatrix} 1 & 1 \\ 0 & 0 \end{bmatrix} \begin{bmatrix} N_1 \\ N_2 \end{bmatrix} = 0$

\vspace{0.5em}

\noindent $N_1 + N_2 = 0$

\vspace{0.5em}

\noindent Eigenvector for $\lambda = 3 \Rightarrow \begin{bmatrix} -1 \\ 0 \end{bmatrix}$

\vspace{0.5em}

\noindent For $\lambda = 4$, $(M - \lambda I)N = 0$

\vspace{0.5em}

\noindent $\begin{bmatrix} 0 & 1 \\ 0 & -1 \end{bmatrix} \begin{bmatrix} N_1 \\ N_2 \end{bmatrix} = 0$

\vspace{0.5em}

\noindent $N_2 = 0$

\vspace{0.5em}

\noindent $-N_2 = 0$

\vspace{0.5em}

\noindent Eigenvector for $\lambda = 4 \Rightarrow \begin{bmatrix} 1 \\ 0 \end{bmatrix}$

\vspace{0.5em}

\noindent Basis for eigenspace $= \left\{ \begin{bmatrix} 1 \\ 0 \end{bmatrix}, \begin{bmatrix} 0 \\ 1 \end{bmatrix} \right\}$

\vspace{0.5em}

\noindent $\therefore$ Since matrix $M$ \& $N$ have same set of eigenvector, they are similar.

