\hspace*{1em} $J_x$ be the topological space.

\vspace{0.5em}

\noindent\textbf{Let $B$ is the basis element.}

\vspace{0.5em}

\noindent\textbf{Let $B$ is a basis of $J_x$.}

\vspace{0.5em}

\noindent Then $B = \{B_1, B_2, \ldots, B_k\}$ has $k$-elements.

\vspace{0.5em}

\noindent Then $J_x = \{U_1, U_2, U_3, \ldots, U_p\}$

\vspace{0.5em}

\noindent Here $U_i$ is the union of the elements of $B$'s

\vspace{0.5em}

\noindent $\therefore, \; p \leq 2^k$. That is $J_x$ has at most $2^k$ open sets.

\vspace{0.5em}

\noindent (ii) Let $S = \{S_1, S_2, \ldots, S_n\}$ be a sub basis of $J_x$.

\vspace{0.5em}

\noindent Then Basis $B = \{B_1, B_2, \ldots, B_k\}$, where $B_i$ is equal to the intersection of elements of $S$

\vspace{0.5em}

\noindent That why: $k \leq 2^n$.

\vspace{0.5em}

\noindent and $J_x = \{U_1, U_2, U_3, \ldots, U_p\}$

\vspace{0.5em}

\noindent Here, $U_i$ is equal to the union of the elements of $B$'s

\vspace{0.5em}

\noindent $\therefore, \; p \leq 2^k$

\vspace{0.5em}

\noindent $\Rightarrow \boxed{p \leq 2^{2^n}}$

\vspace{0.5em}

\noindent \textbf{Imp:} Subbasis $\xrightarrow{\text{Intersection}}$ Basis $\xrightarrow{\text{Union}}$ Topology

\vspace{0.5em}

\noindent \textbf{A is only set with $n$ elements, then It's power set has $2^n$ elements.}

