\noindent $[T_1]$ can be obtained by rotating axes by $\theta_1$, angle counterclockwise taking image w.r.t. new y axis and then rotating back the axes clockwise by $\theta_1$, angle

\[
\therefore [T_1] = \begin{bmatrix} \text{clockwise } \theta_1 \end{bmatrix} \begin{bmatrix} \text{image w.r.t. new y axis} \end{bmatrix} \begin{bmatrix} \text{counter clockwise rotation by } \theta_1 \end{bmatrix}
\]

\[
[T_1] = \begin{bmatrix} \cos\theta_1 & \sin\theta_1 \\ -\sin\theta_1 & \cos\theta_1 \end{bmatrix} \begin{bmatrix} 1 & 0 \\ 0 & -1 \end{bmatrix} \begin{bmatrix} \cos\theta_1 & -\sin\theta_1 \\ \sin\theta_1 & \cos\theta_1 \end{bmatrix}
\]

\[
[T_1] = \begin{bmatrix} \cos\theta_1 & \sin\theta_1 \\ -\sin\theta_1 & \cos\theta_1 \end{bmatrix} \begin{bmatrix} \cos\theta_1 & -\sin\theta_1 \\ -\sin\theta_1 & -\cos\theta_1 \end{bmatrix}
\]

\[
[T_1] = \begin{bmatrix} \cos 2\theta_1 & -\sin 2\theta_1 \\ -\sin 2\theta_1 & -\cos 2\theta_1 \end{bmatrix}
\]

\noindent similarity
\[
[T_2] = \begin{bmatrix} \cos 2\theta_2 & -\sin 2\theta_2 \\ -\sin 2\theta_2 & -\cos 2\theta_2 \end{bmatrix}
\]

\[
[T_2 \circ T_1] = [T_2][T_1]
\]
\[
= \begin{bmatrix} \cos 2\theta_2 & -\sin 2\theta_2 \\ -\sin 2\theta_2 & -\cos 2\theta_2 \end{bmatrix} \begin{bmatrix} \cos 2\theta_1 & -\sin 2\theta_1 \\ -\sin 2\theta_1 & -\cos 2\theta_1 \end{bmatrix}
\]
\[
= \begin{bmatrix} \cos 2(\theta_2 - \theta_1) & \sin 2(\theta_2 - \theta_1) \\ -\sin 2(\theta_2 - \theta_1) & \cos 2(\theta_2 - \theta_1) \end{bmatrix}
\]

\[
[T_2 \circ T_1] = \begin{bmatrix} \cos 2(\theta_1 - \theta_2) & -\sin 2(\theta_1 - \theta_2) \\ \sin 2(\theta_1 - \theta_2) & \cos 2(\theta_1 - \theta_2) \end{bmatrix}
\]

\noindent b) Rotation matrix is given by
\[
\begin{bmatrix} \cos\phi & -\sin\phi \\ \sin\phi & \cos\phi \end{bmatrix}
\]

\noindent $\therefore$ comparing rotation matrix and
\[
[T_2 \circ T_1] \text{ gives } \cos\phi = \cos(2(\theta_1 - \theta_2)) \quad \sin\phi = \sin(2(\theta_1 - \theta_2))
\]

