\[ l_1 \equiv y = \tan\theta_1 x \]
\[ l_2 \equiv y = \tan\theta_2 x \]

\underline{for $l_1$}

reflection of $(x_1, y_1)$ through $l_1$ will fall on the line ``$y = \tan\theta_2 x + \tan\theta_1 x_1 - y_1$''.

\underline{which is ``$T_1$''}

$\rightarrow$ let $(x_1, y_1)$ be foot of $L$ of $(x_1, y_1)$ on $l_1$. Then $(x_1 - x_2, y_1 - y_2 \tan\theta_2)$ is $L$ to $(x_2, y_2 \tan\theta_2)$

\[ (1, \tan\theta_1) \qquad \therefore (x_1 - x_2 \hat{i} + y_1 - y_2 \tan\theta_1 \hat{j}) \cdot (\hat{i} + \tan\theta_1 \hat{j}) = 0 \]

\[ x_2 - x_1 + x_2 \tan^2\theta - y_1 \tan\theta_1 = 0 \]

\[ x_2 = \frac{x_1 + y_1 \tan\theta_1}{1 + \tan^2\theta} = (x_1 + y_1 \tan\theta_1) \cos^2\theta_1 \]

\[ \therefore y_2 = \tan\theta_1 (x_1 + y_1 \tan\theta_1) \cos^2\theta_1 \]
\[ = \tan\theta_1 (x_1 + y_1 \tan\theta_1) \cos\theta_1 \sin\theta_1 \]

\[ \text{let } (x_1 + y_1 \tan\theta_1) \cos\theta_1 = a \]

\[ \therefore T_1 \equiv y = \tan\theta_1 x + \tan\theta_1 x_1 - y_1 \]

\underline{similarly}

\[ T_2 \equiv y = \tan\theta_2 x + \tan\theta_2 x_1 - y_1 \]

