\end{bmatrix}
\]

\noindent For any of the following are true:

\[
a_{11} b_{11} + a_{12} b_{21} + a_{13} b_{31} + a_{14} b_{41} = 1
\]

\noindent First take case for $n = 2$:

\[
\begin{bmatrix}
a_{11} & a_{12} \\
0 & a_{22}
\end{bmatrix}
\begin{bmatrix}
b_{11} & b_{12} \\
b_{21} & b_{22}
\end{bmatrix}
= \begin{bmatrix}
1 & 0 \\
0 & 1
\end{bmatrix}
\]

\[
\begin{aligned}
a_{11} b_{11} + a_{12} b_{21} &= 1 \\
a_{11} b_{12} + a_{12} b_{22} &= 0 \\
a_{22} b_{21} &= 0 \quad \Rightarrow \quad b_{21} = 0 \\
&\Rightarrow \quad B \text{ is also a upper triangular matrix.}
\end{aligned}
\]

\noindent \sout{AB} $= I$ \quad \sout{inverse}

\noindent \sout{assume true for $n = k$} \quad $\Rightarrow$ \quad $\therefore$ true for $n = 2$.

\noindent For $n = k + 1$:

\[
\begin{bmatrix}
a_{11} & a_{12} & \cdots & a_{1k} \\
0 & a_{22} & \cdots & a_{2k} \\
0 & 0 & a_{33} & \cdots & a_{3k} \\
0 & 0 & 0 & a_{44} & \cdots & a_{4k}
\end{bmatrix}
\begin{bmatrix}
b_{11}(1) & b_{12}(2) & \cdots & b_{1k+1}(k+1) \\
a_{11} & b_{21}(2) & \cdots & a_{21}(2) \\
b_{22}(2) & b_{23}(2) & \cdots & b_{2k+1}(2) \\
0 & \cdots & \cdots & 0 \\
b_{41}(2) & b_{42}(2) & \cdots & b_{4k}(2)
\end{bmatrix}
= \begin{bmatrix}
a_{11} & 0 & \cdots & 0 \\
0 & 1 & \cdots & 0 \\
0 & 0 & \cdots & 0 \\
0 & 0 & 0 & 0
\end{bmatrix}
\]

\noindent For the $k$th column: $(i \geq 2)$ \quad $(i \leq k+1)$ \quad $\Rightarrow$

\[
a_{11} b_{11} + a_{12} b_{21} + a_{13} b_{31} + \cdots = 0
\]

\[
\Rightarrow \quad b_{k+2}(2) = b_{k+1}(3) = \cdots = b_{k+1}(k) = 0
\]

\noindent $\therefore$ hence proved for $k+1$.

\[
\Rightarrow \quad \therefore \text{ by induction, this is true for any } k \geq 2.
\]

\[
\therefore \text{ True for } n = k \text{ as well}
\]

\[
\Rightarrow \text{ Inverse of } 4 \times 4 \text{ UTM is a U.T.M.}
\]

\[
\therefore \underline{\text{hence proved}}
\]

