\vspace{0.5em}
\hspace*{1em} and $\hat{\mu} \in \mathbb{R}^n$ is a unit vector

\vspace{0.5em}
\hspace*{1em} and $\alpha_i$ is the angle between $\hat{u}$ \& $\hat{v}_i$

\vspace{0.5em}
\hspace*{1em} $\cos \alpha_i = \dfrac{v_i \cdot \mu}{|\mu| v_i} = \dfrac{v_i \cdot \mu}{|v_i|}$ \hspace{2em} as $\mu$ is unit vector, $|\mu| = 1$

\vspace{0.5em}
\hspace*{1em} $\left(\cos \alpha_i\right)^2 = \left(\dfrac{v_i \cdot \mu}{v_i}\right)^2 = 1 - \sin^2 \alpha_i$ \hspace{4em} \begin{minipage}{0.5\textwidth}
\hspace*{4em} when, $v_i \cdot \mu = v_i$ \\
\hspace*{4em} $\cos \alpha_i = 1$ \\
only one case, \\
and for rest all \\
$\cos \alpha_i = 0$
\end{minipage}

\vspace{0.5em}
\hspace*{1em} $\dfrac{n}{i=1} \cos^2 \alpha_i = \dfrac{n}{i=1} \left(1 - \sin^2 \alpha_i\right)$

\vspace{0.5em}
\hspace*{1em} $1 = n - \left(\sin^2 \alpha_1 + \sin^2 \alpha_2 + \ldots + \sin^2 \alpha_n\right)$

\vspace{0.5em}
\hspace*{1em} $1 + \sin^2 \alpha_1 + \sin^2 \alpha_2 + \ldots + \sin^2 \alpha_n = n$

