\noindent\underline{Jackpot}

\vspace{0.5em}

\noindent Since let $E = A_1\vec{x} = \vec{b_1}$ \hfill $E$ can be represented uniquely by $[A_1 \mid \vec{b_1}]$

\vspace{0.5em}

\hspace{2em} $E' = A_2\vec{x} = \vec{b_2}$ \hfill $E'$ can also be represented uniquely by $[A_2 \mid \vec{b_2}]$

\vspace{0.5em}

\noindent Since $E$ and $E'$ have the same solution space,

\vspace{0.5em}

\hspace{2em} Reduced Row Echelon form of $[A_1 \mid \vec{b_1}] = [A_2 \mid \vec{b_2}]$

\vspace{0.5em}

\noindent Since we get RREF of $[A_1 \mid \vec{b_1}]$ by elementary row operations,

\vspace{0.5em}

\hspace{2em} $[RREF A_1 \mid \vec{b_1}] = E_n E_{n-1} \cdots E_1 A_1$

\vspace{0.5em}

\noindent Also,

\vspace{0.5em}

\hspace{2em} $[RREF A_2 \mid \vec{b_2}] = E_n' E_{n-1}' \cdots E_1' A_2$

\vspace{0.5em}

\noindent Since $[RREF A_2 \mid \vec{b_2}] = [RREF A_1 \mid \vec{b_1}]$

\vspace{0.5em}

\hspace{2em} $\Rightarrow E_{n-1} E_{n-1}' \cdots E_1 [A_1 \mid \vec{b_1}] = E_n' E_{n-1}' \cdots E_1' [A_2 \mid \vec{b_2}]$

\vspace{0.5em}

\noindent Since elementary matrices are equivalent to identity

\vspace{0.5em}

\hspace{2em} They are invertible and there inverse is also elementary,

\vspace{0.5em}

\hspace{2em} $\therefore [A_1 \mid \vec{b_1}] = E_1^{-1} E_2^{-1} \cdots E_{n-1}^{-1} E_n^{-1} E_{n-1}' \cdots E_1' [A_2 \mid \vec{b_2}]$

\vspace{0.5em}

\hspace{2em} $\therefore$ \sout{can be} \sout{by} using elementary row operations on $A_2$

\vspace{0.5em}

\hspace{2em} $\therefore [A_1 \mid \vec{b_1}]$ is equivalent to $[A_2 \mid \vec{b_2}]$

\vspace{0.5em}

\noindent Hence \boxed{E is equivalent $E'$}

\end{document}

