\noindent (a) \underline{Ans} \quad $f \circ g = [g][f]$ \hfill given: \quad $f: V \to V$ \\
\hspace*{2.5em} $g \circ f = [f][g]$ \hfill \hspace{1.5em} $g: V \to V$

\vspace{0.3em}

\noindent for linearity the function should satisfy following condition

\noindent General cond\textsuperscript{n} for linearity: for any function ``$f$''.

\vspace{0.3em}

\noindent (i) \quad $f(\vec{x}+\vec{y}) = f(\vec{x}) + f(\vec{y})$ \hfill \fbox{$f(\vec{x}) = g(\vec{x})$}

\noindent (ii) \quad $f(t\vec{x}) = t\,f(\vec{x})$

\vspace{0.3em}

\noindent \fbox{$g(\vec{x}) = V(\vec{x})$} \hfill (3)

\vspace{0.3em}

\noindent \fbox{$g(\vec{x}+\vec{y}) = g(\vec{x}) + g(\vec{y})$}

\vspace{0.3em}

\noindent \fbox{$g(\vec{y}) = V(\vec{y})$} \hfill (3)

\vspace{0.3em}

\noindent from equat\textsuperscript{n} (3)

\hspace*{2em} $g(\vec{x}+\vec{y}) = V(\vec{x}+\vec{y})$ \\
\hspace*{2em} $= V(\vec{x}) + V(\vec{y})$

\vspace{0.3em}

\noindent \fbox{$g(\vec{x}+\vec{y}) = g(\vec{x}) + g(\vec{y})$}

\vspace{0.3em}

\noindent \fbox{$g(t\vec{x}) = t\,g(\vec{x})$}

\vspace{0.3em}

\noindent $\therefore$ so, $g$ \underline{is linear}.

\vspace{0.3em}

\noindent b) \underline{Ans} $B = \{b_1, b_2, b_3, \ldots, b_n\}$ is basis for $V$.

\noindent To show: $f(B) = \{f(b_1), f(b_2), \ldots, f(b_n)\}$ is also basis for $V$

\vspace{0.3em}

\noindent $\therefore$ If $B$ is a basis for $V$ then, $f(B)$ too is a basis for $V$

