\noindent Such that (1) is satisfied.

\noindent \underline{Finding $P$:}

\[
\begin{bmatrix} 3 & 0 \\ 0 & 4 \end{bmatrix} \begin{bmatrix} x & y \\ z & w \end{bmatrix} = \begin{bmatrix} x & y \\ z & w \end{bmatrix} \begin{bmatrix} 4 & 1 \\ 0 & 3 \end{bmatrix}
\]

\noindent this gives 4 eqns as
\begin{align*}
& 3x_0 = 4x_0 \quad \text{or} \quad 3y_0 = x + 3y \\
& 4x_0z = 4z \quad \text{or} \quad 4w = z + 3w
\end{align*}

\noindent $\therefore x = 0, \quad z = w$.

\noindent Hence $P = \begin{bmatrix} 0 & a \\ b & b \end{bmatrix} \quad \forall\ a, b \in \mathbb{R}$.

