\noindent (1) Sol\textsuperscript{n}: As per given question; $\hat{u} \cdot \hat{v}_i = \cos(\alpha_i) \quad [1 \leq i \leq n]$

\noindent and, $\hat{u} \cdot \hat{v}_i$ denotes length of the projection of $\hat{u}$ onto on $\hat{v}_i$

\noindent So, by definition; $\|\hat{u}\| = \sqrt{(\hat{u} \cdot \hat{v}_1)^2 + (\hat{u} \cdot \hat{v}_2)^2 + \cdots + (\hat{u} \cdot \hat{v}_n)^2}$

\begin{align*}
&\Rightarrow \|\hat{u}\|^2 = \cos^2(\alpha_1) + \cos^2(\alpha_2) + \cdots + \cos^2(\alpha_n) \\
&\Rightarrow \sum_{i=1}^{m} \cos^2(\alpha_i) = 1 \quad [\because \|\hat{u}\| = 1]
\end{align*}

then, $1 + \sin^2\alpha_1 + \cdots + \sin^2\alpha_n$

\begin{align*}
&= 1 + (1 - \cos^2\alpha_1) + \cdots + (1 - \cos^2\alpha_n) \\
&= 1 + n - \sum_{i=1}^{m} \cos^2(\alpha_i) \\
&= 1 + m - 1 \\
&= m \text{ (Proved)}
\end{align*}

