\noindent (i) \quad $\hat{u} = (u_1 \cdot \hat{v}_1) \hat{v}_1 + (u_2 \cdot \hat{v}_2) \hat{v}_2 + \cdots + (u_n \cdot \hat{v}_n) \hat{v}_n$

\begin{align*}
\hat{u} &= c_1 |\hat{v}_1|^2 = c_1 = \hat{v}_1 \cdot \hat{u} \\
&\text{similarly} \quad c_i = \hat{v}_i \cdot \hat{u} \\
\therefore \hat{u} &= \sum_{i=1}^{n} (\hat{u} \cdot \hat{v}_i) \hat{v}_i \\
&= \sum_{i=1}^{n} \left( \|\hat{u}\| \|\hat{v}_i\| \cos \alpha_i \right) \hat{v}_i \\
&= \sum_{i=1}^{n} (\cos \alpha_i) \hat{v}_i \\
\| \hat{u} \|^2 &= \sum_{i=1}^{n} \cos^2 \alpha_i \\
&= 1 = \sum_{i=1}^{n} \left( 1 - \sin^2 \alpha_i \right) \\
&= 1 = n - \sum_{i=1}^{n} \sin^2 \alpha_i \\
&= 1 + \sum_{i=1}^{n} \sin^2 \alpha_i = n \\
&\Rightarrow 1 + \sin^2 \alpha_1 + \sin^2 \alpha_2 + \ldots \sin^2 \alpha_n = n
\end{align*}
